INSERT INTO workspace_members (
    workspace_member_id, workspace_id, member_id, status, joined, role
) VALUES (
    seq_workspace_members.NEXTVAL, #{workspaceId}, #{memberId}, #{status}, SYSDATE, #{role}
)
